import {lineStatus,LINE_RATE_WH,UTILITY_BATTERY_WH} from './power-lines.js';
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderLineHarvest(record,state,{enabled=true}={}){
 if(record.type!=='engineer')return '';
 const t=record.task?.kind==='LINE'?record.task:null,live=record.task&&['RUNNING','PAUSED'].includes(record.task.state),active=t&&live;
 const status=t?lineStatus(state,t.anchor.spanId):null,ready=enabled&&state.engineerBuilt&&state.leg===1;
 const button=(action,label,disabled=false)=>`<button data-fleet-task="${action}" ${!enabled||disabled?'disabled':''}>${label}</button>`;
 return `<section class="fleetTask" aria-label="Conductor harvesting"><div class="sectionHeading"><span>UTILITY / LINE COUPLER</span><b>${t?esc(t.stage):'READY'}</b></div><h3>${t?.packId?'Harvest &amp; deliver':'Perch, recharge, remain deployed'}</h3><p>Utility approaches a clear point on an energized wire, aligns and clamps on, stops its rotors, then charges its onboard battery to 90%. It stays perched until recalled. The line’s finite reserve supplies every unit collected.</p><p class="hint">Southern transmission corridor · 36–43 m high. Fly near the desired section before assigning, or dispatch from the bike. At least 25% battery and 30% hull are required.</p>${t?`<p class="taskBadge">${esc(t.state)} · ${esc(status.reason)} · ${status.remainingWh.toFixed(1)} Wh in circuit</p><p role="status">${esc(t.reason)}</p><p>Collected ${t.harvestedWh.toFixed(1)} Wh · onboard ${record.battery.toFixed(1)}% / ${UTILITY_BATTERY_WH} Wh · ${active&&t.state==='RUNNING'&&t.stage==='CHARGING'?LINE_RATE_WH.toFixed(1):'0'} Wh/s input</p>`:''}<div class="taskActions">${button('line','PERCH NEAREST LIVE WIRE',!ready||live)}${active?(t.state==='PAUSED'?button('resume','RESUME COUPLING'):button('pause','PAUSE CHARGING'))+button('cancel','RELEASE & RETURN'):''}</div><p class="hint">${!state.engineerBuilt?'Fit the engineer module in Workshop.':state.leg!==1?'Supported conductors are in Ghost Signal.':'South feed is live; restore the substation relay and grid coupler to energize the northern feed. Release clears the wire before another flight order. Use Harvest & deliver below to charge a removable pack and return it to the trailer.'}</p></section>`;
}
